{
  "name": "Thorlabs APT电机控制器",
  "name_en": "Thorlabs APT Motor Controller",
  "manufacturer": "Thorlabs",
  "description": "用于驱动 Thorlabs APT 兼容电动位移台、旋转台等精密运动机构的控制器，可执行回零、绝对/相对移动、点动及位置与状态读取，常用于光学实验中的精密定位、对准和扫描。",
  "description_en": "A controller for Thorlabs APT-compatible motorized stages, rotation stages, and other precision motion mechanisms. It supports homing, absolute/relative moves, jog motion, and position/status readback, and is commonly used for precise positioning, alignment, and scanning in optical experiments.",
  "tag_hints": [
    "motorized positioning",
    "optical stage control",
    "rotation stage",
    "linear translation stage",
    "homing",
    "jog motion",
    "closed-loop position control"
  ],
  "actions": [
    {
      "action_name": "auto-serial_number",
      "description": "获取序列号",
      "description_en": "Get the serial number"
    },
    {
      "action_name": "auto-model_number",
      "description": "获取型号",
      "description_en": "Get the model number"
    },
    {
      "action_name": "auto-name",
      "description": "获取设备名称",
      "description_en": "Get the device name"
    },
    {
      "action_name": "auto-channel",
      "description": "获取控制通道",
      "description_en": "Get the controller channel"
    },
    {
